#!/usr/bin/env python3
import math, random, sys

# Physical constants (SI)
G = 6.67430e-11            # gravitational constant
c = 2.99792458e8           # speed of light
M_sun = 1.98847e30         # solar mass

def schwarzschild_radius(M):
    """Schwarzschild radius r_s = 2GM/c^2"""
    return 2 * G * M / c**2

def horizon_area(r_s):
    """Area of a spherical horizon A = 4π r_s^2"""
    return 4 * math.pi * r_s**2

def hawking_temperature(M):
    """Hawking temperature T = ħ c^3 / (8π G k_B M)"""
    hbar = 1.054571817e-34
    k_B = 1.380649e-23
    return hbar * c**3 / (8 * math.pi * G * k_B * M)

def planck_length():
    """Planck length l_P = sqrt(ħ G / c^3)"""
    hbar = 1.054571817e-34
    return math.sqrt(hbar * G / c**3)

def random_mass():
    """Generate a random astrophysical mass between 5 and 50 solar masses."""
    return random.uniform(5, 50) * M_sun

def run_trials(num_trials=10000):
    failures = 0
    max_area = 0.0
    max_temp = 0.0
    max_len = 0.0
    min_temp = float('inf')
    for i in range(num_trials):
        M = random_mass()
        r_s = schwarzschild_radius(M)
        A = horizon_area(r_s)
        T = hawking_temperature(M)
        lP = planck_length()
        # Dimensionless area (A / l_P^2)
        dimless_area = A / lP**2
        # Guard against negative or zero temperature due to rounding
        if T <= 0:
            failures += 1
            continue
        if dimless_area > max_area:
            max_area = dimless_area
        if T > max_temp:
            max_temp = T
        if T < min_temp:
            min_temp = T
        if lP > max_len:
            max_len = lP
    if failures == 0:
        print("ALL PASS")
    else:
        print(f"FAILURES: {failures} out of {num_trials}")
    print(f"MAX DIMENSIONLESS AREA: {max_area:.3e}")
    print(f"MAX HAWKING TEMPERATURE: {max_temp:.3e} K")
    print(f"MIN HAWKING TEMPERATURE: {min_temp:.3e} K")
    print(f"PLANCK LENGTH: {max_len:.3e} m")

if __name__ == "__main__":
    run_trials()
